export const MOB_THEMES=[{name:'Lobo das falésias',spirit:'Eco errante',kind:'wolf',color:'#829181'},{name:'Cão das cinzas',spirit:'Brasa faminta',kind:'wolf',color:'#8f6552'},{name:'Escorpião de Sárion',spirit:'Espectro das dunas',kind:'scorpion',color:'#b79c65'},{name:'Lince de Vesper',spirit:'Eco de geada',kind:'wolf',color:'#c1d5d8'},{name:'Guardião do Eclipse',spirit:'Luz corrompida',kind:'construct',color:'#7ca99c'},{name:'Sentinela partida',spirit:'Alma da Cidadela',kind:'construct',color:'#8797a5'},{name:'Devorador de Nhal',spirit:'Sombra do Abismo',kind:'demon',color:'#8c7cac'},{name:'Autômato imperial',spirit:'Orbe de Aster',kind:'construct',color:'#ad9b75'},{name:'Escorpião prismático',spirit:'Reflexo hostil',kind:'scorpion',color:'#95cfdb'},{name:'Arauto estelar',spirit:'Centelha do Vazio',kind:'demon',color:'#9b9bd2'},{name:'Guardião ancestral',spirit:'Eco da Primeira Luz',kind:'construct',color:'#d1c39c'},{name:'Devorador primordial',spirit:'Fragmento da Origem',kind:'demon',color:'#cfb6da'}];
export function drawMob(g,e,t){const theme=MOB_THEMES[e.theme||0],c=e.boss?'#5d526e':theme.color,kind=e.archetype||'wolf',rage=e.boss&&e.hp/e.maxHp<.3,energy=rage?'#ff8570':e.boss?'#e4bd86':'#b9e1d7',step=e.moving?Math.sin(t*10):0;const poly=(pts,fill,stroke='#13202a')=>{g.beginPath();pts.forEach((p,n)=>n?g.lineTo(...p):g.moveTo(...p));g.closePath();g.fillStyle=fill;g.fill();g.strokeStyle=stroke;g.lineWidth=.7;g.stroke();};const line=(a,b,color,w=2)=>{g.beginPath();g.moveTo(...a);g.lineTo(...b);g.strokeStyle=color;g.lineWidth=w;g.stroke();};const oval=(x,y,rx,ry,color)=>{g.beginPath();g.ellipse(x,y,rx,ry,0,0,Math.PI*2);g.fillStyle=color;g.fill();};const shade=g.createLinearGradient(-15,-50,20,0);shade.addColorStop(0,'#1b2936');shade.addColorStop(.35,c);shade.addColorStop(.48,e.boss?'#a6a1b0':c);shade.addColorStop(.6,c);shade.addColorStop(1,'#16202c');g.save();
if(kind==='spirit'){const glow=g.createRadialGradient(0,-25,1,0,-25,34);glow.addColorStop(0,energy+'cc');glow.addColorStop(1,energy+'00');g.fillStyle=glow;g.fillRect(-34,-59,68,68);poly([[0,-48],[9,-30],[5,-18],[15,-5],[0,-11],[-13,-3],[-5,-22],[-9,-32]],shade);oval(-3,-31,1.5,1.5,'#f0f9e1');oval(3,-31,1.5,1.5,'#f0f9e1');for(let j=0;j<3;j++)oval(Math.sin(t*2+j*2)*16,-25+Math.cos(t*2+j*2)*17,.9,.9,energy);}
else if(kind==='scorpion'){for(let side of [-1,1])for(let n=0;n<4;n++){line([side*7,-12+n*4],[side*(18+n*2),-8+n*5+step],c,2);line([side*(18+n*2),-8+n*5+step],[side*24,3+n*3],c,1.2);}oval(0,-7,12,14,shade);poly([[-9,-18],[-12,-26],[0,-34],[12,-26],[9,-18]],shade);for(let side of [-1,1]){line([side*9,-24],[side*24,-35],c,4);poly([[side*21,-32],[side*28,-41],[side*32,-36],[side*29,-28],[side*24,-31]],shade);}g.beginPath();g.moveTo(0,2);g.bezierCurveTo(21,3,23,-29,10,-39);g.strokeStyle=c;g.lineWidth=4;g.stroke();poly([[9,-43],[17,-39],[11,-35]],energy);}
else if(kind==='construct'||kind==='demon'){const demon=kind==='demon';for(let side of [-1,1]){line([side*7,-26],[side*(10+step),-1],c,7);poly([[side*4,-13],[side*13,-14],[side*16,1],[side*4,2]],shade);line([side*14,-49],[side*23,-25],c,6);poly([[side*9,-56],[side*22,-52],[side*25,-42],[side*12,-43]],shade);if(demon){poly([[side*9,-49],[side*37,-72],[side*47,-31],[side*31,-42],[side*26,-26]],'#322a40',c);poly([[side*5,-67],[side*16,-82],[side*13,-63]],c);}}poly([[-13,-55],[0,-62],[14,-55],[11,-29],[0,-24],[-11,-29]],shade);for(let n=0;n<3;n++)line([-10,-48+n*7],[10,-48+n*7],'#243344',1);poly([[0,-51],[5,-44],[0,-37],[-5,-44]],energy);poly([[-8,-59],[-7,-68],[0,-75],[8,-68],[9,-59],[0,-55]],shade);line([-5,-64],[-1,-64],energy,1.5);line([2,-64],[6,-64],energy,1.5);if(e.boss){line([23,-27],[29,-74],'#887958',3);poly([[29,-82],[36,-70],[29,-59],[22,-70]],energy);}}
else {for(let side of [-1,1]){line([-10,-14],[ -15+side*4+step*side,5],side<0?'#34444a':c,3);line([11,-14],[14+side*4-step*side,5],side<0?'#34444a':c,3);}oval(0,-15,21,11,shade);poly([[12,-20],[13,-35],[23,-31],[31,-20],[26,-12],[17,-12]],shade);poly([[14,-32],[12,-45],[20,-35]],c);poly([[22,-31],[23,-43],[27,-32]],c);oval(25,-27,1.3,1.2,energy);line([26,-18],[31,-19],'#16252d',2);g.beginPath();g.moveTo(-18,-15);g.quadraticCurveTo(-32,-15,-30,-34);g.strokeStyle=c;g.lineWidth=5;g.stroke();for(let n=0;n<8;n++)line([-14+n*4,-22+Math.sin(n)*2],[-12+n*4,-15+Math.sin(n)*2],'#c4cfbe55',.7);}
g.restore();}

for(let n=12;n<21;n++)MOB_THEMES.push({...MOB_THEMES[(n-12)%12],name:["Vigia Estelar","Predador do Zodíaco","Autômato do Vazio"][n%3],spirit:"Espectro Cósmico"});
